`,l.jsx(t.h2,{children:"Process"}),`
`,l.jsx(t.p,{children:"I started with matchmaking. Surprisingly, the initial implementation was simpler than I expected. I maintained a server-side queue (an in-memory array) that pairs players as they connect. Once two players are available, a game session is instantiated and both clients are assigned to the same room."}),`
`,l.jsx(t.p,{children:"For private matches, I implemented room codes that are automatically generated when a player wants to invite a friend. I used nanoId to generate unique playerId, gameId, and room codes. This kept identifiers short, collision-resistant, and easy to handle across the client and server."}),`
`,l.jsx(t.p,{children:"For real-time communication, I used WebSockets. Instead of pushing for full real-time optimization immediately, I intentionally simplified it to near-real-time updates at 20 FPS. This allowed me to focus on getting the core game logic correct - handling card state, validating moves, resolving conflicts - before worrying about micro-optimizations. The server acts as the authoritative source of truth, and clients simply render the updated state."}),`
`,l.jsx(t.p,{children:"On the frontend, I used React to handle UI state and drag-and-drop mechanics for card interactions. Ensuring that animations felt smooth while remaining consistent with server updates required careful separation between visual state and game state."}),`
`,l.jsx(t.p,{children:"The entire backend and supporting services were deployed on AWS. Hosting the WebSocket server and managing infrastructure in the cloud gave me hands-on experience with deployment pipelines and production environment configuration."}),`
`,l.jsx(t.hr,{}),`
`,l.jsx(t.h2,{children:"What I Learned"}),`
`,l.jsxs(t.ul,{children:[`
`,l.jsxs(t.li,{children:[`
`,l.jsx(t.p,{children:"Implementing real-time multiplayer logic with WebSockets"}),`
`]}),`
`,l.jsxs(t.li,{children:[`
`,l.jsx(t.p,{children:"Designing authoritative server architecture to prevent desync"}),`
`]}),`
`,l.jsxs(t.li,{children:[`
`,l.jsx(t.p,{children:"Using nanoId for scalable, collision-resistant identifiers"}),`
`]}),`
`,l.jsxs(t.li,{children:[`
`,l.jsx(t.p,{children:"Managing deployment and infrastructure on AWS"}),`
`]}),`
`,l.jsxs(t.li,{children:[`
`,l.jsx(t.p,{children:"Handling drag-and-drop mechanics cleanly in React"}),`
`]}),`
`,l.jsxs(t.li,{children:[`
`,l.jsx(t.p,{children:"Balancing performance with development velocity"}),`
`]}),`
`]}),`
`,l.jsx(t.hr,{}),`
`,l.jsx(t.h2,{children:"What's Next"}),`
`,l.jsx(t.p,{children:"The next step is improving UI polish and responsiveness. The core game works, but the experience can feel sharper - better animations, clearer feedback, and improved mobile responsiveness would elevate the gameplay significantly."}),`
`,l.jsx(t.p,{children:"I also want to improve matchmaking reliability and scalability. Moving from in-memory queues to a more persistent or distributed approach would make the system more production-ready. Performance tuning beyond the current 20 FPS update cycle is another area I’d like to explore once the infrastructure becomes more robust."})]})}function LE(i={}){const{wrapper:t}=i.components||{};return t?l.jsx(t,{...i,children:l.jsx(Cy,{...i})}):Cy(i)}function My(i){const t={h2:"h2",hr:"hr",li:"li",p:"p",strong:"strong",ul:"ul",...i.components};return l.jsxs(l.Fragment,{children:[l.jsx(t.hr,{}),`
`,l.jsx(t.h2,{children:"Introduction"}),`
`,l.jsx(t.p,{children:"This project started as a simple experiment to learn web scraping. I just wanted to pull some movie data and understand how scraping pipelines worked end-to-end."}),`
`,l.jsx(t.p,{children:"But as I was building it, I realized the data itself was actually interesting. Instead of stopping at a CSV file, I decided to turn it into something visual — a dashboard that shows where the top 100 most popular movies on IMDb were filmed. I’ve always thought 3D globe visualizations on the web looked cool, so this felt like the perfect excuse to finally use one."}),`
`,l.jsx(t.p,{children:"The result is a full-stack application that scrapes IMDb every 6 hours via an automated ETL pipeline and visualizes filming locations on an interactive globe."}),`
`,l.jsx(t.hr,{}),`
